--Ejercicio 1SELECT population FROM world  WHERE name = 'Germany'--Ejercicio 2SELECT name, population FROM world  WHERE name IN ('Sweden', 'Norway', 'Denmark');--Ejercicio 3SELECT name, area FROM world  WHERE area BETWEEN 200000 AND 250000--SELECT FROM WORLD TUTORIAL--Ejercicio 1SELECT name FROM worldWHERE population >= 200000000--Ejercicio 2select name, gdp/population from world where population >= 200000000--Ejercicio 3select name, population/1000000 from world where continent = 'South America'--Ejercicio 4select name, population from world where name in ('France','Germany','Italy')--Ejercicio 5select name from world where name like '%United%'--Ejercicio 6SELECT name, population, area FROM worldwhere area > 3000000 or population > 250000000--Ejercicio 7select name, population, area from worldwhere population > 250000000 xor area > 3000000--Ejercicio 8select name, round(population/1000000.0,2) as population, round((gdp/1000000000.0),2) as GDPfrom world where continent = 'South America'--Ejercicio 9select name, round(gdp/population,-3) as "per-capita GDP" from world where gdp >= 1000000000000--Ejercicio 10SELECT name, capital  FROM world WHERE length(name) = length(capital)--Ejercicio 11SELECT name, capitalFROM worldwhere name <> capitaland left(name,1) = left(capital,1)--Ejercicio 12--Sin terminar, All vowels